/**
 * @file src/lib/lazyTabMounts.ts
 * Defer Svelte tab panel mounts until first switchTab — reduces idle DOM at boot.
 */

import { mount, type Component } from 'svelte';
import type { GameRuntime } from '../types/game.js';
import { handleChunkLoadFailure } from './chunkLoadRecovery.ts';

type TabMountFn = () => void;

const mountFns = new Map<string, TabMountFn>();
const mounted = new Set<string>();
const readyPromises = new Map<string, Promise<void>>();
const readyResolvers = new Map<string, () => void>();
const readyRejectors = new Map<string, (err: unknown) => void>();

function ensureReadyPromise(tabArg: string): Promise<void> {
  let promise = readyPromises.get(tabArg);
  if (!promise) {
    promise = new Promise<void>((resolve, reject) => {
      readyResolvers.set(tabArg, resolve);
      readyRejectors.set(tabArg, reject);
    });
    readyPromises.set(tabArg, promise);
  }
  return promise;
}

function markTabReady(tabArg: string): void {
  readyResolvers.get(tabArg)?.();
  readyResolvers.delete(tabArg);
  readyRejectors.delete(tabArg);
}

function markTabFailed(tabArg: string, err: unknown): void {
  readyRejectors.get(tabArg)?.(err);
  readyResolvers.delete(tabArg);
  readyRejectors.delete(tabArg);
}

export function registerLazyTabMount(tabArg: string, fn: TabMountFn): void {
  mountFns.set(tabArg, () => {
    fn();
    markTabReady(tabArg);
  });
}

function mountTabPanelIntoTarget(tabId: string, ComponentType: Component): void {
  const target = document.getElementById(tabId);
  if (!target || target.getAttribute('data-svelte-ui') === '1') return;
  target.innerHTML = '';
  target.setAttribute('data-svelte-ui', '1');
  mount(ComponentType, { target });
}

export function registerLazyTabMountAsync(
  tabArg: string,
  tabId: string,
  loader: () => Promise<{ default: Component }>,
): void {
  ensureReadyPromise(tabArg);
  mountFns.set(tabArg, () => {
    void loader()
      .then(({ default: ComponentType }) => {
        mountTabPanelIntoTarget(tabId, ComponentType);
        markTabReady(tabArg);
      })
      .catch((err: unknown) => {
        mounted.delete(tabArg);
        markTabFailed(tabArg, err);
        handleChunkLoadFailure(`tab:${tabArg}`, err);
      });
  });
}

export function isLazyTabMounted(tabArg: string): boolean {
  return mounted.has(tabArg);
}

function refreshTabDisplay(tabArg: string, game: GameRuntime): void {
  switch (tabArg) {
    case 'boutique':
      game.updateShopDisplay?.();
      game.updateUpgradesDisplay?.();
      break;
    case 'sacados':
      game.updateItemsDisplay?.();
      game.updateIncubatorsDisplay?.();
      game.updateEggsDisplay?.();
      break;
    case 'pokedex':
      game.updatePokedexDisplay?.();
      break;
    case 'quests':
      game.updateQuestsDisplay?.();
      game.updateAchievementsDisplay?.();
      break;
    case 'tower':
      game.updateTowerDisplay?.();
      game.updateTowerShopDisplay?.();
      break;
    case 'expeditions':
      game.updateExpeditionsDisplay?.();
      break;
    case 'teamrocket':
      game.updateTeamRocketDisplay?.();
      break;
    case 'arenas':
      game.updateArenasDisplay?.();
      game.updateEliteFourDisplay?.();
      break;
    default:
      break;
  }
}

/** Kick off lazy tab Svelte mount on first visit (does not wait for async import). */
export function ensureLazyTabMounted(tabArg: string): void {
  if (mounted.has(tabArg)) return;
  const fn = mountFns.get(tabArg);
  if (!fn) return;
  mounted.add(tabArg);
  fn();
}

/** Await lazy tab Svelte mount, then refresh panel data. */
export async function awaitLazyTabReady(tabArg: string): Promise<void> {
  if (!mountFns.has(tabArg)) return;

  if (!mounted.has(tabArg)) {
    const promise = readyPromises.get(tabArg) ?? ensureReadyPromise(tabArg);
    ensureLazyTabMounted(tabArg);
    try {
      await promise;
    } catch {
      return;
    }
  }

  const g =
    typeof globalThis !== 'undefined'
      ? (globalThis as { game?: GameRuntime }).game
      : undefined;
  if (g) refreshTabDisplay(tabArg, g);
}
