/**
 * Shared main-stat boost factors for header display and combat effective stats.
 * Mirrors the potion + synergy + collection stack from getEffectiveStats (main-stats path).
 */
import type { HeaderStatKey, TeamStatBlock } from '../bus/snapshots.js';
import type { GameRuntime } from '../types/game.js';
import { getActiveStatBoostKey } from './statBoostKey.ts';

export type MainStatBoostFactors = TeamStatBlock;

export interface AccumulateMainStatBoostOptions {
    /** When false, skips temporary team potions (activeStatBoosts). Default true. */
    includePotions?: boolean;
    /** When false, skips team synergy multipliers. Default true. */
    includeSynergies?: boolean;
    /** When false, skips collection defense multipliers. Default true. */
    includeCollections?: boolean;
}

function applyPotionBoosts(
    factors: MainStatBoostFactors,
    game: GameRuntime,
): void {
    const boosts = game.activeStatBoosts;
    if (!Array.isArray(boosts)) return;
    for (let i = 0; i < boosts.length; i++) {
        const boost = boosts[i];
        if (!boost) continue;
        const key = getActiveStatBoostKey(boost);
        if (key === 'all') {
            factors.hp += boost.value;
            factors.attack += boost.value;
            factors.spattack += boost.value;
            factors.defense += boost.value;
            factors.spdefense += boost.value;
            factors.speed += boost.value;
        } else if (key === 'hp') factors.hp += boost.value;
        else if (key === 'attack') factors.attack += boost.value;
        else if (key === 'spattack') factors.spattack += boost.value;
        else if (key === 'defense') factors.defense += boost.value;
        else if (key === 'spdefense') factors.spdefense += boost.value;
        else if (key === 'speed') factors.speed += boost.value;
    }
}

function applySynergyBoosts(
    factors: MainStatBoostFactors,
    game: GameRuntime,
): void {
    if (typeof game.getActiveSynergies !== 'function') return;
    const synergies = game.getActiveSynergies();
    factors.hp += (synergies.max_hp_mult ?? 1) - 1;
    factors.attack += (synergies.attack_mult ?? 1) - 1;
    factors.spattack += (synergies.spattack_mult ?? 1) - 1;
    factors.defense += (synergies.defense_mult ?? 1) - 1;
    factors.spdefense += (synergies.spdefense_mult ?? 1) - 1;
    factors.speed += synergies.speed_mult ? synergies.speed_mult - 1 : 0;
}

function applyCollectionBoosts(
    factors: MainStatBoostFactors,
    game: GameRuntime,
): void {
    const collBonuses =
        typeof game.getCollectionBonuses === 'function' ? game.getCollectionBonuses() : {};
    const collDefense = collBonuses.defense_mult || 0;
    if (collDefense > 0) {
        factors.defense += collDefense;
        factors.spdefense += collDefense;
    }
}

/** Boost multipliers (base 1) from potions, synergies, and collections. */
export function accumulateMainStatBoostFactors(
    game: GameRuntime,
    options: AccumulateMainStatBoostOptions = {},
): MainStatBoostFactors {
    const includePotions = options.includePotions !== false;
    const includeSynergies = options.includeSynergies !== false;
    const includeCollections = options.includeCollections !== false;
    const factors: MainStatBoostFactors = {
        hp: 1,
        attack: 1,
        spattack: 1,
        defense: 1,
        spdefense: 1,
        speed: 1,
    };

    if (includePotions) applyPotionBoosts(factors, game);
    if (includeSynergies) applySynergyBoosts(factors, game);
    if (includeCollections) applyCollectionBoosts(factors, game);

    return factors;
}

function auraMultiplier(game: GameRuntime): number {
    return typeof game.getTalentStackBonus === 'function'
        ? 1 + game.getTalentStackBonus('aura')
        : 1;
}

export interface DisplayedHeaderStatOptions extends AccumulateMainStatBoostOptions {}

/**
 * Value shown in header stat chips (main stats + potions + synergies + collections + aura).
 * HP delegates to getPlayerMaxHp (or growth variant without potions).
 */
export function getDisplayedHeaderStat(
    game: GameRuntime,
    statKey: HeaderStatKey,
    options: DisplayedHeaderStatOptions = {},
): number {
    const includePotions = options.includePotions !== false;

    if (statKey === 'hp') {
        if (!includePotions && typeof game.getPlayerMaxHpForGrowthAnalysis === 'function') {
            return game.getPlayerMaxHpForGrowthAnalysis();
        }
        return typeof game.getPlayerMaxHp === 'function' ? game.getPlayerMaxHp() : 0;
    }

    const main = game.playerMainStats ?? {};
    const base = Number((main as Record<string, number>)[statKey]) || 0;
    const factors = accumulateMainStatBoostFactors(game, options);
    return Math.floor(base * auraMultiplier(game) * factors[statKey]);
}

/** Build all header display stats at once. */
export function buildDisplayedHeaderStats(game: GameRuntime): TeamStatBlock {
    const keys: HeaderStatKey[] = ['hp', 'attack', 'spattack', 'defense', 'spdefense', 'speed'];
    const stats = {} as TeamStatBlock;
    for (const key of keys) {
        stats[key] = getDisplayedHeaderStat(game, key);
    }
    return stats;
}
