/**
 * @file src/lib/creatureCardSnapshot.ts
 * Build CreatureSnapshot fields needed for team/pension/storage cards.
 */

import type { CreatureSnapshot } from '../bus/snapshots.js';
import type { CreatureData } from '../types/creature.js';
import type { GameRuntime } from '../types/game.js';
import { uiPokemonName } from '@card-ui/i18n';
import { getHeldItemBadgeHTML, getPokerusBadgeHTML } from '@card-ui/badges';
import {
  cardPrestigeStoneIconUrl,
  cardResolvePrestigeCosts,
} from './cardPrestigeUi.js';
import {
  getAnchorCatchUpXpMult,
  getEffectivePrestigeAndLevel,
  getResonanceCap,
  isRegionalResonanceActive,
} from './regionalResonance.ts';
import { GEN5_SUBSTITUTE_SPRITE, getPokemonSpriteUrl } from './cardSprites.js';

const _spriteUrlCache = new Map<string, string>();

export type CardSpriteContext = 'team' | 'pension';

type AnimatedSpritesConfig = {
  active?: boolean;
  team?: boolean;
  pension?: boolean;
  all?: boolean;
};

type SpriteResolveOpts = {
  context: CardSpriteContext;
  animatedConfig?: AnimatedSpritesConfig | null;
  preferStatic?: boolean;
};

/** Whether GIF sprites are enabled for team/pension card snapshots. */
export function isAnimatedSpritesEnabledForContext(
  gm: GameRuntime,
  context: CardSpriteContext,
): boolean {
  const cfg = gm.animatedSprites as AnimatedSpritesConfig | undefined;
  if (!cfg) return false;
  if (cfg.all) return true;
  if (context === 'team' && cfg.team) return true;
  if (context === 'pension' && cfg.pension) return true;
  return false;
}

/** Clear cached card sprite URLs (call when toggling animatedSprites). */
export function clearCardSpriteUrlCache(): void {
  _spriteUrlCache.clear();
}

function buildSpriteOpts(
  context: CardSpriteContext,
  gm: GameRuntime | null | undefined,
  preferStatic: boolean,
): SpriteResolveOpts {
  const baseCfg = gm?.animatedSprites as AnimatedSpritesConfig | undefined;
  let animatedConfig: AnimatedSpritesConfig | null = baseCfg ?? null;
  if (preferStatic && animatedConfig) {
    animatedConfig = { ...animatedConfig, team: false, pension: false, all: false };
  }
  return { context, animatedConfig };
}

/** Live sprite URL (animatedSprites + card context via getPokemonSpriteUrl opts). */
export function resolveCardSpriteUrl(
  name: string,
  isShiny: boolean,
  context: CardSpriteContext,
  fallback = '',
  preferStatic = false,
  gm?: GameRuntime | null,
): string {
  const url = getPokemonSpriteUrl(
    name,
    isShiny,
    false,
    buildSpriteOpts(context, gm, preferStatic),
  );
  return url || fallback;
}

function getSpriteUrl(
  name: string,
  isShiny: boolean,
  context: CardSpriteContext,
  gm: GameRuntime,
): string {
  const animated = isAnimatedSpritesEnabledForContext(gm, context);
  const cacheKey = `${context}|${name}|${isShiny ? 1 : 0}|${animated ? 'gif' : 'png'}`;
  const cached = _spriteUrlCache.get(cacheKey);
  if (cached) return cached;
  const url =
    resolveCardSpriteUrl(
      name,
      isShiny,
      context,
      GEN5_SUBSTITUTE_SPRITE,
      !animated,
      gm,
    ) || GEN5_SUBSTITUTE_SPRITE;
  _spriteUrlCache.set(cacheKey, url);
  return url;
}

function shardKeyForCreature(name: string, rarity: string): string {
  const fn = (globalThis as { getShardKey?: (n: string, r: unknown) => string }).getShardKey;
  return fn ? fn(name, rarity) : name;
}

function creatureUid(c: CreatureData): string {
  const prestige = Number(c.prestige) || 0;
  return typeof (c as { uid?: string }).uid === 'string' && (c as { uid: string }).uid
    ? (c as { uid: string }).uid
    : `${c.name}|${prestige}|${c.isShiny ? 1 : 0}`;
}

/** Fallback when enrich fails — keeps roster index aligned with game.playerTeam. */
export function minimalCreatureSnapshot(gm: GameRuntime, c: CreatureData): CreatureSnapshot {
  const prestige = Number(c.prestige) || 0;
  const isAlive = typeof c.isAlive === 'function' ? c.isAlive(gm) : Number(c.currentHp) > 0;
  return {
    uid: creatureUid(c),
    name: c.name,
    type: c.type ?? 'normal',
    secondaryType: c.secondaryType ?? null,
    level: Number(c.level) || 1,
    rarity: c.rarity ?? 'common',
    isShiny: !!c.isShiny,
    isShadow: !!c.isShadow,
    isEpic: !!c.isEpic,
    isBoss: !!c.isBoss,
    isFavorite: !!c.isFavorite,
    currentHp: Number(c.currentHp) || 0,
    maxHp: Number(c.maxHp) || 1,
    attack: Number(c.attack) || 0,
    spattack: Number(c.spattack) || 0,
    defense: Number(c.defense) || 0,
    spdefense: Number(c.spdefense) || 0,
    speed: Number(c.speed) || 0,
    prestige,
    tier: c.tier ?? 0,
    heldItem: c.heldItem ?? null,
    passiveTalent: c.passiveTalent ?? null,
    ivHP: c.ivHP ?? 0,
    ivAttack: c.ivAttack ?? 0,
    ivSpAttack: c.ivSpAttack ?? 0,
    ivDefense: c.ivDefense ?? 0,
    ivSpDefense: c.ivSpDefense ?? 0,
    ivSpeed: c.ivSpeed ?? 0,
    ultimateAbility: null,
    ultimateCharge: 0,
    megaStoneUnlocked: false,
    megaVariant: 'X',
    exp: Math.max(0, Number(c.exp) || 0),
    expToNext: Math.max(1, Number(c.expToNext) || 1),
    displayName: uiPokemonName(gm, c.name),
    spriteUrl: getSpriteUrl(c.name, !!c.isShiny, 'team', gm),
    shardCount: 0,
    prestigeCost: 1,
    prestigeStoneCost: 1,
    prestigeStoneCount: 0,
    prestigeStoneIconUrl: '',
    prestigeReady: false,
    isAlive,
    heldBadgeHtml: '',
    pokerusBadgeHtml: '',
  };
}

export function enrichCreatureSnapshot(
  gm: GameRuntime,
  c: CreatureData,
  spriteContext: CardSpriteContext = 'team',
): CreatureSnapshot {
  const prestige = Number(c.prestige) || 0;
  const maxLevel = 100 + prestige * 10;
  const shardKey = shardKeyForCreature(c.name, c.rarity);
  const shardCount = Number(gm.shards?.[shardKey]) || 0;
  const catchUpCosts = cardResolvePrestigeCosts(gm, c);
  const prestigeCost = catchUpCosts.shards;
  const prestigeStoneCost = catchUpCosts.stones;
  const stones = gm.items?.prestige_stone;
  const currentPrestigeStones = stones != null ? Number(stones) || 0 : 0;
  const expToNext = Math.max(1, Number(c.expToNext) || 1);
  const exp = Math.max(0, Number(c.exp) || 0);
  const isAlive = typeof c.isAlive === 'function' ? c.isAlive(gm) : true;
  const resonanceActive = isRegionalResonanceActive(gm);
  const eff = getEffectivePrestigeAndLevel(c, gm);
  const cap = resonanceActive ? getResonanceCap(gm) : null;
  const anchorCatchUpXpMult = getAnchorCatchUpXpMult(c, gm);

  return {
    uid: creatureUid(c),
    name: c.name,
    type: c.type,
    secondaryType: c.secondaryType ?? null,
    level: c.level,
    rarity: c.rarity,
    isShiny: !!c.isShiny,
    isShadow: !!c.isShadow,
    isEpic: !!c.isEpic,
    isBoss: !!c.isBoss,
    isFavorite: !!c.isFavorite,
    currentHp: c.currentHp,
    maxHp: c.maxHp,
    attack: c.attack,
    spattack: c.spattack,
    defense: c.defense,
    spdefense: c.spdefense,
    speed: c.speed,
    prestige,
    tier: c.tier ?? 0,
    heldItem: c.heldItem ?? null,
    passiveTalent: c.passiveTalent ?? null,
    ivHP: c.ivHP,
    ivAttack: c.ivAttack,
    ivSpAttack: c.ivSpAttack,
    ivDefense: c.ivDefense,
    ivSpDefense: c.ivSpDefense,
    ivSpeed: c.ivSpeed,
    ultimateAbility: c.ultimateAbility
      ? { name: String(c.ultimateAbility.name ?? ''), description: String(c.ultimateAbility.description ?? '') }
      : null,
    ultimateCharge: c.ultimateCharge ?? 0,
    megaStoneUnlocked: !!c.megaStoneUnlocked,
    megaVariant: String(c.megaVariant ?? 'X'),
    exp,
    expToNext,
    displayName: uiPokemonName(gm, c.name),
    spriteUrl: getSpriteUrl(c.name, !!c.isShiny, spriteContext, gm),
    shardCount,
    prestigeCost,
    prestigeStoneCost,
    prestigeStoneCount: currentPrestigeStones,
    prestigeStoneIconUrl: cardPrestigeStoneIconUrl(),
    prestigeReady:
      c.level >= maxLevel &&
      shardCount >= prestigeCost &&
      currentPrestigeStones >= prestigeStoneCost,
    isAlive,
    heldBadgeHtml: getHeldItemBadgeHTML(c),
    pokerusBadgeHtml: getPokerusBadgeHTML(c),
    effectivePrestige: eff.capped ? eff.prestige : undefined,
    effectiveLevel: eff.capped ? eff.level : undefined,
    resonanceActive: resonanceActive || undefined,
    resonanceCapped: eff.capped || undefined,
    resonanceCapSimLevel: cap?.simulatedLevel,
    anchorCatchUpXpMult: anchorCatchUpXpMult > 1 ? anchorCatchUpXpMult : undefined,
  };
}
