let getGameInstance: (() => GameRuntime) | null = null;

/** Wire command handlers after `gameManager` creates the Game instance (avoids static import cycle). */
export function bindGameCommandHandlers(getGame: () => GameRuntime): void {
  getGameInstance = getGame;
}

function requireGame(): GameRuntime {
  if (!getGameInstance) {
    throw new Error('[commandHandlers] Game not initialized — call bindGameCommandHandlers()');
  }
  const instance = getGameInstance();
  if (instance == null) {
    throw new Error('[commandHandlers] Game instance is null');
  }
  return instance;
}

const G = (): GameRuntime => requireGame();

type HandlerFn = (cmd: GameCommand) => void;

const handlers = new Map<string, HandlerFn>();

/**
 * Register a command handler. Uses generic narrowing so that the handler
 * receives the exact command type inferred from `type`.
 */
function register<T extends GameCommand['type']>(
  type: T,
  fn: (cmd: Extract<GameCommand, { type: T }>) => void,
): void {
  handlers.set(type, fn as HandlerFn);
}

