register('OPEN_ZONE_MAP', () => {
  void (async () => {
    await ensureLazyModalBeforeShowAsync('zoneMapModal');
    if (G().updateZoneSelector) G().updateZoneSelector();
    const el = document.getElementById('zoneMapModal');
    if (el) el.classList.add('show');
    const btn = document.getElementById('zoneMapBtn');
    if (btn) btn.setAttribute('aria-expanded', 'true');
  })();
});
register('CLOSE_ZONE_MAP', () => {
  const active = document.activeElement;
  if (active instanceof HTMLElement) active.blur();
  const el = document.getElementById('zoneMapModal');
  if (el) el.classList.remove('show');
  const btn = document.getElementById('zoneMapBtn');
  if (btn) btn.setAttribute('aria-expanded', 'false');
});
register('CHANGE_ZONE', (cmd) => {
  if (G().changeZone) G().changeZone(cmd.zone);
  publish({
    type: Evt.ZONE_CHANGED,
    zone: cmd.zone,
    region: G().currentRegion ?? 'kanto',
    maxReachedZone: G().maxReachedZone ?? cmd.zone,
    zoneName: String(G().currentZoneName ?? ''),
  });
});
register('CHANGE_REGION', (cmd) => {
  if (G().changeRegion) G().changeRegion(cmd.region);
  // ZONE_CHANGED is published by changeRegionLogic via publishZoneChanged() on success.
});

