// ─── Modals ───

register('CLOSE_MODAL', (cmd) => {
  const el = document.getElementById(cmd.modalId);
  if (el) el.classList.remove('show');
  publish({ type: Evt.MODAL_CLOSED, modalId: cmd.modalId });
  // Zone tier modal additional cleanup (was in closeZoneTierModal)
  if (cmd.modalId === 'zoneTierModal' && game) {
    game.isZoneTierModalOpen = false;
    const interval = game._zoneTierModalCooldownInterval;
    if (interval) {
      clearInterval(interval);
      game._zoneTierModalCooldownInterval = null;
    }
  }
});
register('OPEN_MODAL', (cmd) => {
  void (async () => {
    if (cmd.modalId === 'statsModal') {
      await ensureLazyModalBeforeShowAsync('statsModal');
      publish({ type: Evt.MODAL_OPENED, modalId: 'statsModal' });
      return;
    }
    if (cmd.modalId === 'bonusModal') {
      await ensureLazyModalBeforeShowAsync('bonusModal');
      const g = G();
      if (typeof g.openBonusModal === 'function') {
        g.openBonusModal();
      } else {
        const el = document.getElementById('bonusModal');
        if (el) el.classList.add('show');
      }
      return;
    }
    await ensureLazyModalBeforeShowAsync(cmd.modalId);
    const el = document.getElementById(cmd.modalId);
    if (el) el.classList.add('show');
  })();
});

