/**
 * Reset scroll position when switching Extras panel tabs / sub-tabs.
 */

export function resetElementScroll(el: HTMLElement | null | undefined): void {
    if (!(el instanceof HTMLElement) || !el.isConnected) return;
    el.scrollTop = 0;
}

export function resetBoutiqueSubTabScroll(subTabName: string): void {
    const panel = document.getElementById(`shop-${subTabName}`);
    const scroll = panel?.querySelector('.shop-subtab-scroll');
    resetElementScroll(scroll instanceof HTMLElement ? scroll : null);
}

function resetBoutiqueActiveSubTabScroll(): void {
    const boutique = document.getElementById('boutiqueTab');
    const active = boutique?.querySelector('.sub-tab-content:not([hidden])');
    const scroll = active?.querySelector('.shop-subtab-scroll');
    resetElementScroll(scroll instanceof HTMLElement ? scroll : null);
}

export function resetExtrasMainTabScroll(tabName: string): void {
    if (tabName === 'boutique') {
        resetBoutiqueActiveSubTabScroll();
        return;
    }
    resetElementScroll(document.getElementById(`${tabName}Tab`));
}

export function resetQuestsTabScroll(): void {
    resetElementScroll(document.getElementById('questsTab'));
}

export function resetRecyclerSubTabScroll(): void {
    const recycleur = document.getElementById('shop-recycleur');
    const scroll = recycleur?.querySelector('.shop-subtab-scroll');
    resetElementScroll(scroll instanceof HTMLElement ? scroll : null);
}

export function resetPokedexTabScroll(): void {
    resetElementScroll(document.getElementById('pokedexTab'));
}

export function scheduleExtrasScrollReset(run: () => void): void {
    requestAnimationFrame(() => {
        requestAnimationFrame(run);
    });
}
