/**
 * @file src/bus/facadeDebug.ts
 * Optional instrumentation for the game event facade.
 * Enable: localStorage.setItem('poketime:facadeDebug', '1') then reload.
 */

import type { GameEventType } from './events.js';
import { writeConsole } from '../lib/devLog.ts';

function facadeConsoleTable(data: unknown): void {
  if (!isFacadeDebugEnabled()) return;
  const t = (globalThis as { console?: { table?: (d: unknown) => void } }).console?.table;
  if (typeof t === 'function') t(data);
}

const STORAGE_KEY = 'poketime:facadeDebug';
const STALE_WARN_MS = 30_000;
const RATE_WINDOW_MS = 5_000;

const _publishCounts: Record<string, number> = {};
const _lastPublishAt: Record<string, number> = {};
const _subscriberCounts: Record<string, number> = {};
/** Timestamps of recent publishes per event (for Hz estimation). */
const _publishTimestamps: Record<string, number[]> = {};
let _warnInterval: ReturnType<typeof setInterval> | null = null;
let _rateWindowStart = 0;

type PublishRateSample = {
  label: string;
  startAt: number;
  baselineHz: Record<string, number>;
};

let _activeRateSample: PublishRateSample | null = null;

export function isFacadeDebugEnabled(): boolean {
  if (typeof localStorage === 'undefined') return false;
  try {
    return localStorage.getItem(STORAGE_KEY) === '1';
  } catch {
    return false;
  }
}

export function enableFacadeDebug(): void {
  if (typeof localStorage !== 'undefined') localStorage.setItem(STORAGE_KEY, '1');
}

export function disableFacadeDebug(): void {
  if (typeof localStorage !== 'undefined') localStorage.removeItem(STORAGE_KEY);
}

export function trackFacadePublish(eventType: string): void {
  if (!isFacadeDebugEnabled()) return;
  const now = Date.now();
  _publishCounts[eventType] = (_publishCounts[eventType] ?? 0) + 1;
  _lastPublishAt[eventType] = now;
  if (!_publishTimestamps[eventType]) _publishTimestamps[eventType] = [];
  const ts = _publishTimestamps[eventType];
  ts.push(now);
  if (_rateWindowStart === 0) _rateWindowStart = now;
  const cutoff = now - RATE_WINDOW_MS;
  while (ts.length > 0 && (ts[0] ?? now) < cutoff) ts.shift();
}

export function trackFacadeSubscribe(eventType: string, delta: number): void {
  if (!isFacadeDebugEnabled()) return;
  _subscriberCounts[eventType] = Math.max(0, (_subscriberCounts[eventType] ?? 0) + delta);
}

/** Clear publish timestamps (e.g. before an idle facade rate sample). */
export function resetFacadePublishWindow(): void {
  for (const k of Object.keys(_publishTimestamps)) {
    _publishTimestamps[k] = [];
  }
  _rateWindowStart = Date.now();
}

/** Estimated publish rate (Hz) over the last RATE_WINDOW_MS. */
export function getFacadePublishRates(): Record<string, number> {
  const now = Date.now();
  const cutoff = now - RATE_WINDOW_MS;
  const rates: Record<string, number> = {};
  for (const [type, ts] of Object.entries(_publishTimestamps)) {
    let count = 0;
    for (const t of ts) {
      if (t >= cutoff) count++;
    }
    rates[type] = count > 0 ? (count / RATE_WINDOW_MS) * 1000 : 0;
  }
  return rates;
}

export function startFacadeDebugWatcher(): void {
  if (!isFacadeDebugEnabled() || _warnInterval != null) return;
  _warnInterval = setInterval(() => {
    const now = Date.now();
    for (const [type, subs] of Object.entries(_subscriberCounts)) {
      if (subs <= 0) continue;
      const last = _lastPublishAt[type];
      if (last == null || now - last > STALE_WARN_MS) {
        writeConsole(
          'warn',
          [`[GameFacade:debug] ${type}: ${subs} subscriber(s), no publish in ${STALE_WARN_MS / 1000}s (count=${_publishCounts[type] ?? 0})`],
        );
      }
    }
  }, STALE_WARN_MS);
}

export function getFacadeDebugStats(): {
  publishCounts: Record<string, number>;
  subscriberCounts: Record<string, number>;
  lastPublishAt: Record<string, number>;
  publishRatesHz: Record<string, number>;
} {
  return {
    publishCounts: { ..._publishCounts },
    subscriberCounts: { ..._subscriberCounts },
    lastPublishAt: { ..._lastPublishAt },
    publishRatesHz: getFacadePublishRates(),
  };
}

export function logFacadeDebugSummary(): void {
  const stats = getFacadeDebugStats();
  writeConsole('log', ['[GameFacade:debug] publish counts (session total)']);
  facadeConsoleTable(stats.publishCounts);
  writeConsole('log', [`[GameFacade:debug] publish rates Hz (last ${RATE_WINDOW_MS / 1000}s window)`]);
  facadeConsoleTable(stats.publishRatesHz);
}

/** Snapshot current sliding-window Hz; call endPublishRateSample() after a combat session. */
export function startPublishRateSample(label = 'sample'): void {
  if (!isFacadeDebugEnabled()) return;
  _activeRateSample = {
    label,
    startAt: Date.now(),
    baselineHz: { ...getFacadePublishRates() },
  };
}

export function endPublishRateSample(): {
  label: string;
  durationMs: number;
  deltaHz: Record<string, number>;
} | null {
  if (!_activeRateSample) return null;
  const endHz = getFacadePublishRates();
  const durationMs = Date.now() - _activeRateSample.startAt;
  const deltaHz: Record<string, number> = {};
  const keys = new Set([...Object.keys(_activeRateSample.baselineHz), ...Object.keys(endHz)]);
  for (const key of keys) {
    deltaHz[key] = (endHz[key] ?? 0) - (_activeRateSample.baselineHz[key] ?? 0);
  }
  const result = { label: _activeRateSample.label, durationMs, deltaHz };
  if (isFacadeDebugEnabled()) {
    writeConsole('log', [`[GameFacade:debug] rate sample "${result.label}" (${durationMs}ms)`]);
    facadeConsoleTable(deltaHz);
  }
  _activeRateSample = null;
  return result;
}

/** @internal Vitest only */
export function resetFacadeDebugForTests(): void {
  for (const k of Object.keys(_publishCounts)) delete _publishCounts[k];
  for (const k of Object.keys(_lastPublishAt)) delete _lastPublishAt[k];
  for (const k of Object.keys(_subscriberCounts)) delete _subscriberCounts[k];
  for (const k of Object.keys(_publishTimestamps)) delete _publishTimestamps[k];
  _rateWindowStart = 0;
  _activeRateSample = null;
}

/** Expose on globalThis in dev for console inspection */
export function installFacadeDebugGlobal(): void {
  if (typeof globalThis === 'undefined') return;
  const g = globalThis as Record<string, unknown>;
  g.__facadeDebug = {
    enable: enableFacadeDebug,
    disable: disableFacadeDebug,
    stats: getFacadeDebugStats,
    rates: getFacadePublishRates,
    resetWindow: resetFacadePublishWindow,
    log: logFacadeDebugSummary,
    startSample: startPublishRateSample,
    endSample: endPublishRateSample,
  };
}

export type { GameEventType };
