/**
 * Inverse l'état replié/déplié des contrôles de filtre du Stockage.
 * Utilise game.isStorageControlsCollapsed (doit être défini sur l'objet game).
 */
export function toggleStorageControls() {
    if (typeof game === 'undefined' || !game) return;

    game.isStorageControlsCollapsed = !game.isStorageControlsCollapsed;

    const controlsContent = document.getElementById('storageControlsContent');
    const controlsIcon = document.getElementById('storageControlsToggleIcon');
    const controlsBtn = document.getElementById('storageControlsToggleBtn');

    if (!controlsContent || !controlsIcon) return;

    if (game.isStorageControlsCollapsed) {
        controlsContent.style.display = 'none';
        controlsIcon.textContent = '\u25B6';
        if (controlsBtn) controlsBtn.classList.add('active');
    } else {
        controlsContent.style.display = 'block';
        controlsIcon.textContent = '\u25BC';
        if (controlsBtn) controlsBtn.classList.remove('active');
    }
}

/**
 * Badge HTML pour l'objet tenu sur une carte créature (en haut à droite).
 * @param {Object} creature - Créature avec heldItem
 * @returns {string} HTML ou chaîne vide
 */
export function getHeldItemBadgeHTML(creature: CreatureData | null | undefined): string {
    if (!creature || !creature.heldItem) return '';
    const item = getHeldItem(creature.heldItem);
    if (!item) return '';
    const gameRef = typeof game !== 'undefined' ? game : null;
    const name = getLocalizedHeldItemLabel(gameRef, creature.heldItem).replace(/"/g, '&quot;');
    if (item.img) {
        return `<img src="${item.img}" class="creature-card-held-item" alt="${name}" title="${name}">`;
    }
    return `<span class="creature-card-held-item creature-card-held-item-icon" title="${name}">${item.icon || 'OBJ'}</span>`;
}

/**
 * Badge HTML pour le Pokérus sur une carte créature (en haut à gauche).
 * @param {Object} creature - Créature avec éventuel Pokérus
 * @returns {string} HTML ou chaîne vide
 */
export function getPokerusBadgeHTML(creature: CreatureData | null | undefined): string {
    if (!creature || typeof creature.hasActivePokerus !== 'function') return '';
    if (!creature.hasActivePokerus()) return '';
    return `<img src="img/PKRS.png" class="creature-card-pokerus" alt="PKRS" title="Pokérus">`;
}

/** Met en surbrillance la zone de dépôt sous le doigt pendant un drag tactile. */
export function updateTouchDropHighlight(clientX: number, clientY: number): void {
    document.querySelectorAll('.team-drag-over').forEach((el) => el.classList.remove('team-drag-over'));
    const stack =
        typeof document.elementsFromPoint === 'function'
            ? document.elementsFromPoint(clientX, clientY)
            : (() => {
                  const hit = document.elementFromPoint(clientX, clientY);
                  return hit ? [hit] : [];
              })();
    for (let i = 0; i < stack.length; i++) {
        const raw = stack[i];
        if (!(raw instanceof Element)) continue;
        const teamCard = raw.closest('#teamList .creature-card');
        if (teamCard) {
            teamCard.classList.add('team-drag-over');
            return;
        }
        const teamEmpty = raw.closest('#teamList .team-slot-empty');
        if (teamEmpty) {
            teamEmpty.classList.add('team-drag-over');
            return;
        }
        const storageCard = raw.closest('#storageList .creature-card[data-storage-index]');
        if (storageCard) {
            storageCard.classList.add('team-drag-over');
            return;
        }
        const storageList = raw.closest('#storageList.storage-drop-zone');
        if (storageList) {
            storageList.classList.add('team-drag-over');
            return;
        }
        const pensionCard = raw.closest('#pensionList .creature-card');
        if (pensionCard) {
            pensionCard.classList.add('team-drag-over');
            return;
        }
        const pensionZone = raw.closest('#pensionList .pension-drop-zone');
        if (pensionZone) {
            pensionZone.classList.add('team-drag-over');
            return;
        }
    }
}

/**
 * Touch drag (mobile) : long press sur la carte pour activer le drag, puis fantôme qui suit le doigt (comme PC).
 * game doit exposer _setCreatureTouchDrag(src, index, el) et _onCreatureTouchEnd(clientX, clientY).
 */
export function bindTouchDragToCreatureCard(
    game: GameRuntime,
    card: HTMLElement,
    src: string,
    index: number,
): void {
    if (!isMobileViewport()) return;

    let touchId: number | null = null;
    let startX = 0;
    let startY = 0;
    let longPressTimer: ReturnType<typeof setTimeout> | null = null;
    let ghostEl: HTMLElement | null = null;
    const moveCancelPx = getTouchDragMoveCancelPx();

    function cancelLongPress() {
        if (longPressTimer) {
            clearTimeout(longPressTimer);
            longPressTimer = null;
        }
        card.classList.remove('touch-drag-arming');
        document.removeEventListener('touchmove', onDocTouchMoveCancel);
        document.removeEventListener('touchend', onDocTouchEndCancel, true);
        document.removeEventListener('touchcancel', onDocTouchEndCancel, true);
    }

    function onDocTouchMoveCancel(e: TouchEvent): void {
        if (!e.touches.length) return;
        const t = Array.from(e.touches).find((x) => x.identifier === touchId);
        if (!t) return;
        const dx = t.clientX - startX, dy = t.clientY - startY;
        if (Math.abs(dx) > moveCancelPx || Math.abs(dy) > moveCancelPx) cancelLongPress();
    }

    function onDocTouchEndCancel(e: TouchEvent): void {
        if (!e.changedTouches?.length) return;
        const t = Array.from(e.changedTouches).find((x) => x.identifier === touchId);
        if (!t) return;
        cancelLongPress();
    }

    function startDrag(): void {
        longPressTimer = null;
        card.classList.remove('touch-drag-arming');
        cancelLongPress();
        if (typeof navigator !== 'undefined' && navigator.vibrate) navigator.vibrate(20);
        game._setCreatureTouchDrag(src, index, card);
        const ghost = card.cloneNode(true);
        if (!(ghost instanceof HTMLElement)) return;
        ghostEl = ghost;
        ghostEl.classList.add('touch-drag-ghost');
        ghostEl.style.position = 'fixed';
        ghostEl.style.left = (startX - card.offsetWidth / 2) + 'px';
        ghostEl.style.top = (startY - card.offsetHeight / 2) + 'px';
        ghostEl.style.width = card.offsetWidth + 'px';
        ghostEl.style.height = card.offsetHeight + 'px';
        ghostEl.style.pointerEvents = 'none';
        ghostEl.style.zIndex = '9999';
        ghostEl.style.opacity = '0.85';
        ghostEl.style.transform = 'scale(1.05)';
        ghostEl.style.boxShadow = '0 8px 24px rgba(0,0,0,0.35)';
        ghostEl.style.transition = 'none';
        document.body.appendChild(ghostEl);
        document.addEventListener('touchmove', onDocTouchMoveDrag, { passive: false });
        document.addEventListener('touchend', onDocTouchEndDrag, true);
        document.addEventListener('touchcancel', onDocTouchEndDrag, true);
    }

    function onDocTouchMoveDrag(e: TouchEvent): void {
        if (!e.touches.length) return;
        const t = Array.from(e.touches).find((x) => x.identifier === touchId);
        if (!t) return;
        e.preventDefault();
        if (ghostEl) {
            ghostEl.style.left = (t.clientX - ghostEl.offsetWidth / 2) + 'px';
            ghostEl.style.top = (t.clientY - ghostEl.offsetHeight / 2) + 'px';
        }
        updateTouchDropHighlight(t.clientX, t.clientY);
        updateDragAutoscroll(t.clientY);
    }

    function onDocTouchEndDrag(e: TouchEvent): void {
        if (!e.changedTouches?.length) return;
        const t = Array.from(e.changedTouches).find((x) => x.identifier === touchId);
        if (!t) return;
        document.removeEventListener('touchmove', onDocTouchMoveDrag);
        document.removeEventListener('touchend', onDocTouchEndDrag, true);
        document.removeEventListener('touchcancel', onDocTouchEndDrag, true);
        if (ghostEl && ghostEl.parentNode) ghostEl.parentNode.removeChild(ghostEl);
        ghostEl = null;
        game._onCreatureTouchEnd(t.clientX, t.clientY);
    }

    card.addEventListener('touchstart', (e: TouchEvent) => {
        if (e.touches.length !== 1) return;
        const target = e.target;
        if (
            target instanceof Element &&
            target.closest('.team-sprite-info-trigger')
        ) {
            return;
        }
        const touch = e.touches[0];
        if (!touch) return;
        touchId = touch.identifier;
        startX = touch.clientX;
        startY = touch.clientY;
        card.classList.add('touch-drag-arming');
        longPressTimer = setTimeout(startDrag, getTouchDragLongPressMs());
        document.addEventListener('touchmove', onDocTouchMoveCancel, { passive: true });
        document.addEventListener('touchend', onDocTouchEndCancel, true);
        document.addEventListener('touchcancel', onDocTouchEndCancel, true);
    }, { passive: true });
}

/** Team cards + counts: Svelte (team store). Keeps drag delegation + combat-end style safety net. */
export function updateTeamDisplayUI(game: GameRuntime): void {
    const teamList = document.getElementById('teamList');
    if (!teamList) return;
    _bindTeamDragDelegation(game, teamList);

    teamList.classList.toggle('sprite-only-mode', !!game.teamSpritesOnly);

    // Undo legacy combat-end cleanup that targeted the first .creature-card (team slot 0).
    teamList.querySelectorAll('.creature-card').forEach((card) => {
        if (!(card instanceof HTMLElement)) return;
        card.style.removeProperty('opacity');
        card.style.removeProperty('pointer-events');
        card.style.removeProperty('cursor');
    });

    // Team cards: Svelte TeamList + team store — sprites via resolveCardSpriteUrl(..., 'team', gm).
}

export function _bindTeamDragDelegation(game: GameRuntime, teamList: TeamListElement): void {
    if (!teamList || teamList._teamDragDelegationBound) return;
    teamList._teamDragDelegationBound = true;

    function getTeamDropTarget(evt: DragEvent): Element | null {
        const target = eventTargetElement(evt.target);
        if (!target) return null;
        const empty = target.closest('.team-slot-empty[data-team-slot-index]');
        if (empty && teamList.contains(empty)) return empty;
        const card = target.closest('.creature-card');
        if (card && teamList.contains(card)) {
            const idx = card.getAttribute('data-team-index');
            if (idx !== null && idx !== '') return card;
        }
        return null;
    }

    function applyDragOverStyle(evt: DragEvent): void {
        evt.preventDefault();
        if (evt.dataTransfer) evt.dataTransfer.dropEffect = 'move';
        updateDragAutoscroll(evt.clientY);
        const target = getTeamDropTarget(evt);
        teamList.querySelectorAll('.team-drag-over').forEach((el) => {
            el.classList.remove('team-drag-over');
        });
        if (target) target.classList.add('team-drag-over');
    }

    // dragstart: CreatureCard (team) sets payload; delegation handles drop targets only.

    teamList.addEventListener('dragenter', applyDragOverStyle);
    teamList.addEventListener('dragover', applyDragOverStyle);

    teamList.addEventListener('dragleave', (evt: DragEvent) => {
        const target = getTeamDropTarget(evt);
        if (!target) return;
        target.classList.remove('team-drag-over');
    });

    teamList.addEventListener('dragend', (evt: DragEvent) => {
        const card = getTeamDropTarget(evt);
        if (!card || !card.classList.contains('creature-card')) return;
        game.onCreatureDragEnd(evt);
    });

    teamList.addEventListener('drop', (evt: DragEvent) => {
        evt.preventDefault();
        let target = getTeamDropTarget(evt);
        if (!target && typeof document.elementsFromPoint === 'function') {
            const stack = document.elementsFromPoint(evt.clientX, evt.clientY);
            for (let i = 0; i < stack.length; i++) {
                const el = stack[i];
                if (!el || !teamList.contains(el)) continue;
                if (el.classList.contains('team-slot-empty')) {
                    target = el;
                    break;
                }
                const card = el.closest('.creature-card');
                if (card && teamList.contains(card)) {
                    target = card;
                    break;
                }
            }
        }
        if (!target) return;
        target.classList.remove('team-drag-over');
        if (target.classList.contains('team-slot-empty')) {
        const teamSlotIndex = parseInt(target.getAttribute('data-team-slot-index') ?? '', 10);
        const toIndex = parseInt(target.getAttribute('data-slot-index') ?? '', 10);
            if (!Number.isFinite(teamSlotIndex)) return;
            game.onTeamDrop(
                evt,
                Number.isFinite(toIndex) ? toIndex : teamSlotIndex,
                teamSlotIndex,
                'empty',
            );
            return;
        }
        const toIndex = parseInt(target.getAttribute('data-team-index') ?? '', 10);
        if (!Number.isFinite(toIndex)) return;
        game.onTeamDrop(evt, toIndex, undefined, 'occupied');
    });
}

