/**
 * @file src/lib/storageRoster.ts
 * Filtered storage roster for Svelte StorageGrid (same rules as storageDisplay.js).
 */

import type { StorageCardSnapshot } from '../bus/snapshots.js';
import type { CreatureData } from '../types/creature.js';
import type { ExpeditionOccupant, GameRuntime } from '../types/game.js';
import { uiPokemonName, uiText } from '@card-ui/i18n';
import { EXPEDITION_DEFINITIONS } from '@snapshot-deps/expeditionDefs';
import { enrichCreatureSnapshot } from './creatureCardSnapshot.js';
import { matchesGenerationFilter } from './nationalDexGeneration.js';

const g = globalThis as Record<string, unknown>;
const expeditionDefs = EXPEDITION_DEFINITIONS as Record<string, { name?: string }>;

type TypeFilterCreature = { type: string; secondaryType?: string | null };

function creatureHasType(creature: TypeFilterCreature, typeKey: string): boolean {
  return creature.type === typeKey || creature.secondaryType === typeKey;
}

export function matchesStorageTypeFilters(
  creature: TypeFilterCreature,
  type1: string,
  type2: string,
): boolean {
  if (type1 === 'all' && type2 === 'all') return true;
  if (type1 !== 'all' && type2 === 'all') return creatureHasType(creature, type1);
  if (type1 === 'all' && type2 !== 'all') return creatureHasType(creature, type2);
  return creatureHasType(creature, type1) && creatureHasType(creature, type2);
}

export type StorageFilterState = {
  searchText: string;
  selectedType: string;
  selectedType2: string;
  selectedGeneration: string;
  favoritesOnly: boolean;
};

export const DEFAULT_STORAGE_FILTERS: StorageFilterState = {
  searchText: '',
  selectedType: 'all',
  selectedType2: 'all',
  selectedGeneration: 'all',
  favoritesOnly: false,
};

export type StorageFilterElementIds = {
  searchInput: string;
  typeFilter: string;
  typeFilter2: string;
  genFilter: string;
  favoriteToggle: string;
};

const DEFAULT_FILTER_ELEMENT_IDS: StorageFilterElementIds = {
  searchInput: 'storageSearchInput',
  typeFilter: 'storageTypeFilter',
  typeFilter2: 'storageTypeFilter2',
  genFilter: 'storageGenFilter',
  favoriteToggle: 'storageFavoriteFilter',
};

export function storageFiltersAreDefault(filters?: StorageFilterState): boolean {
  const f = filters ?? readStorageFiltersFromDom();
  return (
    !f.searchText &&
    f.selectedType === 'all' &&
    f.selectedType2 === 'all' &&
    f.selectedGeneration === 'all' &&
    !f.favoritesOnly
  );
}

export function readStorageFiltersFromDom(
  elementIds: StorageFilterElementIds = DEFAULT_FILTER_ELEMENT_IDS,
  idPrefix = '',
): StorageFilterState {
  if (typeof document === 'undefined') {
    return { ...DEFAULT_STORAGE_FILTERS };
  }
  const searchInput = document.getElementById(
    `${idPrefix}${elementIds.searchInput}`,
  ) as HTMLInputElement | null;
  const typeFilter = document.getElementById(
    `${idPrefix}${elementIds.typeFilter}`,
  ) as HTMLSelectElement | null;
  const typeFilter2 = document.getElementById(
    `${idPrefix}${elementIds.typeFilter2}`,
  ) as HTMLSelectElement | null;
  const genFilter = document.getElementById(
    `${idPrefix}${elementIds.genFilter}`,
  ) as HTMLSelectElement | null;
  const favoriteToggle = document.getElementById(
    `${idPrefix}${elementIds.favoriteToggle}`,
  ) as HTMLButtonElement | null;
  return {
    searchText: searchInput?.value?.toLowerCase() ?? '',
    selectedType: typeFilter?.value ?? 'all',
    selectedType2: typeFilter2?.value ?? 'all',
    selectedGeneration: genFilter?.value ?? 'all',
    favoritesOnly: favoriteToggle?.getAttribute('aria-pressed') === 'true',
  };
}

/** @deprecated Use readStorageFiltersFromDom */
export function readStorageFilters(): StorageFilterState {
  return readStorageFiltersFromDom();
}

export function buildStorageRoster(
  gm: GameRuntime,
  filters?: StorageFilterState,
): {
  creatures: StorageCardSnapshot[];
  filteredCount: number;
  totalOwned: number;
  showEmptyFiltered: boolean;
} {
  const resolvedFilters = filters ?? readStorageFiltersFromDom();
  const searchText = resolvedFilters.searchText.toLowerCase();
  const { selectedType, selectedType2, selectedGeneration, favoritesOnly } = resolvedFilters;
  const expeditionOccupants: ExpeditionOccupant[] =
    typeof gm.getActiveExpeditionOccupants === 'function'
      ? gm.getActiveExpeditionOccupants()
      : [];
  const expeditionCount = expeditionOccupants.length;
  const totalOwned = (gm.storage?.length ?? 0) + expeditionCount;
  const creatures: StorageCardSnapshot[] = [];

  const storage = (gm.storage || []);
  for (let i = 0; i < storage.length; i++) {
    const creature = storage[i];
    if (!creature) continue;
    const localizedName = uiPokemonName(gm, creature.name).toLowerCase();
    if (
      searchText &&
      !creature.name.toLowerCase().includes(searchText) &&
      !localizedName.includes(searchText)
    ) {
      continue;
    }
    if (!matchesStorageTypeFilters(creature, selectedType, selectedType2)) continue;
    if (!matchesGenerationFilter(creature.name, selectedGeneration)) continue;
    if (favoritesOnly && !creature.isFavorite) continue;
    const snap = enrichCreatureSnapshot(gm, creature);
    creatures.push({
      ...snap,
      rosterKey: `storage-${i}-${snap.uid}`,
      source: 'storage',
      storageIndex: i,
      draggable: true,
      cardOpacity: 0.8,
      isExpeditionEntry: false,
    });
  }

  for (const occ of expeditionOccupants) {
    const creature = occ?.data as CreatureData | undefined;
    if (!creature?.name) continue;
    const cname = creature.name.toLowerCase();
    const cnameLocalized = uiPokemonName(gm, creature.name).toLowerCase();
    if (searchText && !cname.includes(searchText) && !cnameLocalized.includes(searchText)) continue;
    if (!matchesStorageTypeFilters(creature, selectedType, selectedType2)) continue;
    if (!matchesGenerationFilter(creature.name, selectedGeneration)) continue;
    if (favoritesOnly && !creature.isFavorite) continue;

    let expeditionName = uiText('storage.expeditionLabel', null, {}, gm) || 'Expedition';
    let expeditionStatus = uiText('storage.inProgress', null, {}, gm) || 'In progress';
    const expIdx = occ.expeditionIndex;
    const exp =
      Number.isInteger(expIdx) && expIdx >= 0
        ? gm.activeExpeditions?.[expIdx]
        : null;
    const expeditionId = exp?.expeditionId;
    if (expeditionId && expeditionDefs[expeditionId]) {
      expeditionName = expeditionDefs[expeditionId].name ?? expeditionName;
    }
    if (exp && typeof exp.endTime === 'number') {
      const remaining = Math.max(0, exp.endTime - Date.now());
      const fmt = g.formatTimeString as ((ms: number) => string) | undefined;
      expeditionStatus =
        remaining > 0
          ? fmt
            ? fmt(remaining)
            : `${Math.ceil(remaining / 60000)} min`
          : uiText('storage.returnReady', null, {}, gm) || 'Return available';
    }

    const expSnap = enrichCreatureSnapshot(gm, creature);
    creatures.push({
      ...expSnap,
      rosterKey: `expedition-${occ.expeditionIndex ?? creatures.length}-${expSnap.uid}`,
      source: 'expedition',
      storageIndex: -1,
      draggable: false,
      cardOpacity: 0.62,
      isExpeditionEntry: true,
      expeditionName,
      expeditionStatus,
    });
  }

  return {
    creatures,
    filteredCount: creatures.length,
    totalOwned,
    showEmptyFiltered: creatures.length === 0 && totalOwned > 0,
  };
}

function creatureUid(c: CreatureData): string {
  const prestige = Number(c.prestige) || 0;
  return typeof (c as { uid?: string }).uid === 'string' && (c as { uid: string }).uid
    ? (c as { uid: string }).uid
    : `${c.name}|${prestige}|${c.isShiny ? 1 : 0}`;
}

function buildStorageCard(gm: GameRuntime, creature: CreatureData, storageIndex: number): StorageCardSnapshot {
  const snap = enrichCreatureSnapshot(gm, creature);
  return {
    ...snap,
    rosterKey: `storage-${storageIndex}-${snap.uid}`,
    source: 'storage',
    storageIndex,
    draggable: true,
    cardOpacity: 0.8,
    isExpeditionEntry: false,
  };
}

/**
 * Fast path when one creature was appended to storage with default filters and no expeditions.
 */
export function tryAppendStorageRoster(
  gm: GameRuntime,
  previousRoster: StorageCardSnapshot[],
): ReturnType<typeof buildStorageRoster> | null {
  if (!storageFiltersAreDefault()) return null;

  const expeditionOccupants: ExpeditionOccupant[] =
    typeof gm.getActiveExpeditionOccupants === 'function'
      ? gm.getActiveExpeditionOccupants()
      : [];
  if (expeditionOccupants.length > 0) return null;

  const storage = gm.storage || [];
  const storageCards = previousRoster.filter((c) => c.source === 'storage' && !c.isExpeditionEntry);
  if (storage.length !== storageCards.length + 1) return null;

  const newIndex = storage.length - 1;
  const creature = storage[newIndex];
  if (!creature) return null;

  for (let i = 0; i < newIndex; i++) {
    const c = storage[i];
    if (!c) return null;
    const expectedKey = `storage-${i}-${creatureUid(c)}`;
    if (storageCards[i]?.rosterKey !== expectedKey) return null;
  }

  const newCard = buildStorageCard(gm, creature, newIndex);
  return {
    creatures: [...previousRoster, newCard],
    filteredCount: previousRoster.length + 1,
    totalOwned: storage.length,
    showEmptyFiltered: false,
  };
}
