/** Long-press delay (ms) before touch drag on team/move rows. */
export const TOUCH_DRAG_LONG_PRESS_MS = 500;

/** Shorter delay on mobile viewports — easier than 500ms hold. */
export const TOUCH_DRAG_LONG_PRESS_MOBILE_MS = 280;

/** Cancel long-press if finger moves more than this (px) before drag starts. */
export const TOUCH_DRAG_MOVE_CANCEL_PX = 15;

export const TOUCH_DRAG_MOVE_CANCEL_MOBILE_PX = 32;

export function getTouchDragLongPressMs(): number {
    if (typeof window !== 'undefined' && typeof window.matchMedia === 'function') {
        if (window.matchMedia('(max-width: 1200px)').matches) {
            return TOUCH_DRAG_LONG_PRESS_MOBILE_MS;
        }
    }
    return TOUCH_DRAG_LONG_PRESS_MS;
}

export function getTouchDragMoveCancelPx(): number {
    if (typeof window !== 'undefined' && typeof window.matchMedia === 'function') {
        if (window.matchMedia('(max-width: 1200px)').matches) {
            return TOUCH_DRAG_MOVE_CANCEL_MOBILE_PX;
        }
    }
    return TOUCH_DRAG_MOVE_CANCEL_PX;
}

if (typeof globalThis !== 'undefined') {
    (globalThis as { TOUCH_DRAG_LONG_PRESS_MS?: number }).TOUCH_DRAG_LONG_PRESS_MS = TOUCH_DRAG_LONG_PRESS_MS;
}
